// Run Once for All Items — set explicitly. This node reasons over the whole
// roster at once (it maps referrer ids to names), so per-item mode is wrong.

const cfg = $('Config').first().json;
const FLOOR = cfg.PROGRAM_FLOOR;                 // '2026-09-01'
const DAYS  = Number(cfg.DAYS_TO_SECOND_PAYMENT); // 35
const MIN   = Number(cfg.MIN_EXPECTED_PEOPLE);    // 200

// Twenty returns { data: { people: [...] }, pageInfo: {...} } per page.
const people = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const batch = (j.data && j.data.people) || j.people || (Array.isArray(j) ? j : null);
  if (Array.isArray(batch)) people.push(...batch);
  else if (j.id) people.push(j); // some n8n versions split arrays into items
}

// ---- Guard: a truncated fetch must fail LOUD, not report an empty list. ----
// If pagination silently breaks, this node sees page 1 only and would report
// "no payouts due" — indistinguishable from a genuinely quiet week. A
// diagnostic that under-reports is worse than none.
if (people.length < MIN) {
  return [{ json: { alert: true, text:
    '\u26a0\ufe0f Referral payout check DID NOT RUN CORRECTLY.\n\n' +
    'Only ' + people.length + ' people were read from Twenty (expected at least ' + MIN + ').\n' +
    'Pagination is probably broken, so this week\u2019s payout list is NOT trustworthy.\n\n' +
    'Check the "Fetch All People (paginated)" node before assuming nothing is owed.'
  } }];
}

const byId = {};
for (const p of people) byId[p.id] = p;

const nameOf = (p) => {
  if (!p) return '(desconocido)';
  const n = p.name || {};
  const s = ((n.firstName || '') + ' ' + (n.lastName || '')).trim();
  return s || String(p.id).slice(0, 8);
};

// start date = coachingStartDate, falling back to signUpDate.
// coachingStartDate was created 2026-08-08 and is null for the whole backfilled
// book, so keying on it alone silently skips every existing athlete.
const startOf = (p) => p.coachingStartDate || p.signUpDate || null;

const today = new Date();
const cutoff = new Date(today.getTime() - DAYS * 86400000)
  .toISOString().slice(0, 10);

const due = [];
for (const p of people) {
  if (!p.referredById) continue;              // 1. must be attributed
  if (p.referralRewardSentDate) continue;     // 2. already paid
  if (p.churnDate) continue;                  // 3. left before month 2
  const start = startOf(p);
  if (!start) continue;                       // no usable date — see below
  if (start > cutoff) continue;               // 4. second payment not due yet
  if (start < FLOOR) continue;                // 5. program floor
  due.push({
    referred: nameOf(p),
    referredId: p.id,
    referrer: nameOf(byId[p.referredById]),
    start,
    leadSource: p.leadSource || '-'
  });
}

// Attributed but with no date at all: cannot be evaluated either way, and
// silently dropping them is how a payout goes missing. Reported separately.
const undated = people.filter(p =>
  p.referredById && !p.referralRewardSentDate && !p.churnDate && !startOf(p)
).map(p => nameOf(p) + ' (referido por ' + nameOf(byId[p.referredById]) + ')');

// A quiet week sends nothing at all — same convention as the daily error digest.
if (!due.length && !undated.length) return [];

let text = '';
if (due.length) {
  text += '\ud83c\udf81 Gift cards pendientes: ' + due.length + '\n\n';
  for (const d of due) {
    text += '\u2022 ' + d.referrer + ' \u2192 refiri\u00f3 a ' + d.referred + '\n';
    text += '   inicio ' + d.start + ' \u00b7 canal ' + d.leadSource + '\n';
  }
  text += '\nAntes de comprar: confirmar el segundo pago en la lista de pagos de TrainingPeaks.\n';
  text += 'Despu\u00e9s de enviar: cargar referralRewardSentDate en el atleta REFERIDO (no en quien refiri\u00f3).\n';
  text += 'Mensaje: sales-playbook.md B9d.';
}
if (undated.length) {
  text += (text ? '\n\n' : '') +
    '\u26a0\ufe0f Referidos sin fecha de inicio (' + undated.length + ') \u2014 no se pueden evaluar:\n\u2022 ' +
    undated.join('\n\u2022 ') +
    '\nCargar coachingStartDate o signUpDate en Twenty.';
}

return [{ json: { alert: false, count: due.length, text } }];
